674:     $timeout = Get-ReplMethodTimeoutSeconds -Method $Method
675: 
676:     # Build as an object and serialize to JSON so request envelopes keep a
677:     # single canonical shape across plugin hosts.
678:     $paramsObject = $null
679:     if ($ParamsYaml) {
680:         $paramsObject = Convert-ReplParamsYamlToObject -ParamsYaml $ParamsYaml
681:     }
682:     $request = New-McpPluginReplRequest -RequestId $requestId -Method $Method -Params $paramsObject
683:     $envelope = ConvertTo-McpPluginJson -InputObject $request -Depth 20 -Compress
684: 
685:     try {
686:         $psi = [System.Diagnostics.ProcessStartInfo]::new()
687:         if ($replExe -match '\.(cmd|bat)$') {
688:             $psi.FileName = $env:ComSpec
689:             $psi.ArgumentList.Add('/c')
690:             $psi.ArgumentList.Add($replExe)
691:         } else {
692:             $psi.FileName = $replExe
693:         }
694:         $psi.ArgumentList.Add('--agent-stdio')
695:         $psi.ArgumentList.Add('--agent')
696:         $psi.ArgumentList.Add($script:AgentName)
697:         $psi.RedirectStandardInput = $true
698:         $psi.RedirectStandardOutput = $true
699:         # Do NOT redirect stderr: mcpserver-repl logs verbose 'info:' lines
700:         # to stderr, and an unread redirected stream blocks the child once
701:         # its pipe buffer fills (Windows ~4 KB), causing WaitForExit to hang.
702:         $psi.UseShellExecute = $false
703:         $psi.CreateNoWindow = $true
704:         Set-ReplProcessWorkspace -StartInfo $psi
705:         # mcpserver-repl writes UTF-8 (with BOM). Without explicit encoding,
706:         # PowerShell decodes as cp437 and BOM bytes (EF BB BF) become box-
707:         # drawing glyphs that break the '^type: error' regex anchor.
708:         $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8
709: 
710:         $proc = [System.Diagnostics.Process]::Start($psi)
711:         $budget = [System.Diagnostics.Stopwatch]::StartNew()
712:         $envFile = Join-Path (Get-ReplInvokeCacheDir) "envelope-$requestId.tmp"
713:         [System.IO.File]::WriteAllText($envFile, $envelope, [System.Text.Encoding]::UTF8)
714:         $copyStream = [System.IO.File]::OpenRead($envFile)
715:         $copyTask = $copyStream.CopyToAsync($proc.StandardInput.BaseStream)
716:         $copyBudget = [int][Math]::Max(1, ($timeout * 1000) - $budget.ElapsedMilliseconds)
717:         if (-not $copyTask.Wait($copyBudget)) {
718:             try { $copyStream.Dispose() } catch { }
719:             try { $proc.Kill($true) } catch { }
720:             try { [void]$proc.WaitForExit(2000) } catch { }
721:             Remove-Item $envFile -ErrorAction SilentlyContinue
722:             return (New-McpPluginReplResult -Success $false -Output '' -Error "mcpserver-repl timed out after ${timeout}s")
723:         }
724:         $copyStream.Dispose()
725:         $proc.StandardInput.Close()
726:         Remove-Item $envFile -ErrorAction SilentlyContinue
727: 
728:         # Drain stdout BEFORE waiting for exit. With a redirected pipe, the
729:         # child blocks on stdout writes once the pipe buffer (~4 KB on
730:         # Windows) fills, and WaitForExit then deadlocks. ReadToEndAsync
731:         # streams the buffer concurrently and resolves when the child closes
732:         # stdout (which happens at process exit).
733:         $readTask = $proc.StandardOutput.ReadToEndAsync()
734:         $readBudget = [int][Math]::Max(1, ($timeout * 1000) - $budget.ElapsedMilliseconds)
735:         if (-not $readTask.Wait($readBudget)) {
736:             try { $proc.Kill($true) } catch { }
737:             try { [void]$proc.WaitForExit(2000) } catch { }
738:             return (New-McpPluginReplResult -Success $false -Output '' -Error "mcpserver-repl timed out after ${timeout}s")
