740:         $output = $readTask.Result
741:         $exitBudget = [int][Math]::Max(1, ($timeout * 1000) - $budget.ElapsedMilliseconds)
742:         if (-not $proc.WaitForExit($exitBudget)) {
743:             try { $proc.Kill($true) } catch { }
744:             try { [void]$proc.WaitForExit(2000) } catch { }
745:             return (New-McpPluginReplResult -Success $false -Output '' -Error "mcpserver-repl timed out after ${timeout}s")
746:         }
747: 
748:         # mcpserver-repl writes a UTF-8 BOM before the YAML doc and may
749:         # interleave logger 'info:' lines on stdout — strip BOM and ignore
750:         # leading log noise so the regex anchor matches the real header.
751:         $output = $output -replace "[\uFEFF]", ''
752:         $isError = $output -match '(?m)^type:\s*error\b'
753:         if ($proc.ExitCode -ne 0 -or $isError) {
754:             return (New-McpPluginReplResult -Success $false -Output $output -ExitCode $proc.ExitCode)
755:         }
756:         # TR-MCP-REPL-016: this is the first proof in the process that the backend
757:         # answers, so it is the safe moment to replay anything the failsafe queue
758:         # captured while it was unreachable. Guarded to run at most once.
759:         Invoke-ReplFailsafeDrainOnFirstSuccess
760:         return (New-McpPluginReplResult -Success $true -Output $output -ExitCode $proc.ExitCode)
761:     }
762:     catch {
763:         $caughtOutput = ''
764:         if (Get-Variable -Name output -Scope Local -ErrorAction SilentlyContinue) {
765:             $caughtOutput = [string]$output
766:         }
767:         $classified = ConvertTo-McpPluginClassifiedError -Output $caughtOutput -ErrorText $_.ToString()
768:         if ($classified.preserved) {
769:             return (New-McpPluginReplResult -Success $false -Output $caughtOutput -Error $classified.message)
770:         }
771:         return (New-McpPluginReplResult -Success $false -Output '' -Error $_.ToString())
772:     }
